//S11: セッション失効 (トークン無効化) — 生成時 標準装備テンプレート
// NextAuth の JWT 戦略では「発行済み JWT を消す」ことができない。そこで User に
// sessionVersion を持たせ、JWT に焼き込んだ版数と DB の現在版数の不一致で失効させる。
// パスワード変更・退会・不正アクセス検知時に revokeAllSessions() を 1 回呼べば、
// その瞬間から既存の全端末のセッションが無効になる (全端末ログアウト)。
//
// 必要な Prisma カラム: model User { ... sessionVersion Int @default(0) }
//
// NextAuth 配線 (authOptions.callbacks):
//   async jwt({ token, user }) {
//     if (user) token.sessionVersion = (user as { sessionVersion?: number }).sessionVersion ?? 0;
//     return token;
//   },
//   async session({ session, token }) {
//     const current = await prisma.user.findUnique({
//       where: { id: token.sub! },
//       select: { sessionVersion: true },
//     });
//     if (!current || isSessionRevoked(token.sessionVersion as number, current.sessionVersion)) {
//       return null as never; // 失効 → 未認証扱い
//     }
//     return session;
//   },

type UserDelegate = {
  update: (args: {
    where: { id: string };
    data: { sessionVersion: { increment: number } };
  }) => Promise<unknown>;
};

/** 指定ユーザーの全セッションを即時失効させる (全端末ログアウト) */
export async function revokeAllSessions(userDelegate: UserDelegate, userId: string): Promise<void> {
  await userDelegate.update({
    where: { id: userId },
    data: { sessionVersion: { increment: 1 } },
  });
}

/** JWT に焼き込まれた版数が DB の現在版数と一致しなければ失効 */
export function isSessionRevoked(
  tokenVersion: number | undefined,
  currentVersion: number,
): boolean {
  return (tokenVersion ?? -1) !== currentVersion;
}
